LAB=[['希腊 lambanein 拿、抓住；相关 lab-、lep-、lemma 等形式','同一历史词族在不同语法形式里改变词干']]
SYLLAB=LAB+[['希腊 syn- 一起 + lambanein → syllambanein → syllabē','把声音组合在一起 → 音节']]
EPILEP=LAB+[['希腊 epi- 在上 + lambanein → epilambanein → epilēpsia','抓住、侵袭 → 疾病发作的名称']]
MOR=[['希腊 mōros 愚笨、迟钝 → 中性形式 mōron','古典形容词成为近代名称的材料'],['近代英语 moron','早期旧医学分类用词，后来主要成为贬损性的日常骂词']]
W += [
E('dilemma','/dɪˈlemə/ 或 /daɪˈlemə/','两难；难以抉择的困境','摆在面前的两条路各有代价，选哪一条都觉得为难。','希腊 di- 两个 + lemma 被提出或接受的前提，组成 dilemma，再经晚期拉丁语借入。lemma 与 lambanein 拿、接受有关。',LAB+[['希腊 di- + lemma → dilemma → 晚期拉丁 dilemma → 英语 dilemma','逻辑论辩中的双重命题 → 日常难以取舍的处境']],'face a dilemma 是面临两难；an ethical dilemma 是伦理上的难题。现代也会泛说棘手的选择，但核心通常有相互冲突的要求或代价。','face a dilemma；an ethical dilemma；resolve a dilemma；the horns of a dilemma。','problem 很宽泛；dilemma 更突出选哪边都难。拼写是两个 m，没有 n。',('She faced a dilemma: accept the promotion or stay close to her family.','她陷入两难：接受晋升，还是留在家人身边。'),('The case raises an ethical dilemma for the research team.','这个案例让研究团队面临一个伦理难题。'),sources=['https://www.etymonline.com/word/dilemma','https://en.wiktionary.org/wiki/dilemma#English']),
E('syllable','/ˈsɪləbəl/','音节','把一个词念出来时，可以听成一下一下的发音节拍；每一拍大致就是一个音节。','希腊 syllabē 原意与把声音收在一起有关，经拉丁 syllaba、法语相关形式借来；结尾 -le 的形态受其他英语词类推影响，并不是 able 能够。',SYLLAB+[['拉丁 syllaba → 古法语 silabe / 英法语 sillable → 英语 syllable','从聚在一起的一组声音，成为发音单位的名称']],'cat 是一个音节，banana 通常是三个音节。数音节要听发音，不能只数元音字母；有些发音里辅音也能承担音节中心。','a stressed syllable；the first syllable；count the syllables；a word with three syllables。','letter 是字母，sound 是声音，syllable 是发音组织成的一节；三者数目不必相同。',('The word “banana” has three syllables.','banana 这个词有三个音节。'),('She stressed the final syllable to correct his pronunciation.','她重读了最后一个音节，纠正他的发音。'),sources=['https://www.etymonline.com/word/syllable','https://en.wiktionary.org/wiki/syllable#English']),
E('syllabic','/sɪˈlæbɪk/','音节的；按音节组织的；成音节的','从一个音节转向某种系统、结构或声音怎样以音节为单位工作。','现代可认出 syllab- + -ic；历史经拉丁 syllabicus 接希腊 syllabikos，不只是现代英语 syllable 换一个词尾。',SYLLAB+[['希腊 syllabikos → 拉丁 syllabicus → 英语 syllabic','音节相关；后用于书写系统、结构和成音节发音']],'syllabic structure 是音节结构；syllabic writing 以音节作书写单位；a syllabic consonant 则是能构成音节核心的辅音。','syllabic structure；a syllabic writing system；a syllabic consonant。','syllabic writing 的符号通常对应音节；alphabetic writing 通常以字母表示更小的语音单位。',('The lesson compares alphabetic and syllabic writing systems.','这节课比较了字母文字与音节文字。'),('In some pronunciations of “button”, the final consonant is syllabic.','在 button 的某些读法中，最后的辅音可以成音节。'),sources=['https://www.etymonline.com/word/syllabic','https://en.wiktionary.org/wiki/syllabic#English']),
E('monosyllabic','英 /ˌmɒnəsɪˈlæbɪk/；美 /ˌmɑːnəsɪˈlæbɪk/','单音节的；回答极简短的','字面上只有一个音节；形容人时，像问什么都只答嗯、是、不。','现代可看 mono- 一个 + syllabic；历史联系希腊、拉丁的单音节词族。词源资料既有拉丁 monosyllabicus 的借入分析，也有 monosyllable + -ic 的英语派生分析。',SYLLAB+[['希腊 monosyllabos → 拉丁 monosyllabus / monosyllabicus','单音节的古典词族'],['英语 monosyllable、monosyllabic','借入分析与英语加 -ic 的分析并存；现代明确对应单音节']],'a monosyllabic word 是单音节词；monosyllabic replies 是非常简短、显得不愿多说的回答。后者是语气描述，不必真的逐字统计每个回答只有一个音节。','a monosyllabic word；monosyllabic replies；become monosyllabic。','quiet 只是话少；monosyllabic 更具体地描写答得短，可能让人感觉冷淡或不耐烦。',('“Door” is a monosyllabic word.','door 是一个单音节词。'),('His monosyllabic replies made the conversation awkward.','他极简短的回答让谈话显得尴尬。'),sources=['https://www.etymonline.com/word/monosyllabic','https://en.wiktionary.org/wiki/monosyllabic#English','https://www.collinsdictionary.com/dictionary/english/monosyllabic','https://www.oxfordlearnersdictionaries.com/definition/english/monosyllabic']),
E('polysyllabic','英 /ˌpɒlisɪˈlæbɪk/；美 /ˌpɑːlisɪˈlæbɪk/','多音节的','一个词念起来有好几拍，常是看起来较长、读起来也较长的词。','poly- 多 + syllabic；历史联系中世纪拉丁 polysyllabus、希腊 polysyllabos，英语加 -ic 的构形也可能参照法语 polysyllabique。',SYLLAB+[['希腊 poly- + syllabē → polysyllabos → 中世纪拉丁 polysyllabus','多个音节的'],['英语 polysyllabic，可能参照法语 polysyllabique','以 -ic 形式表达多音节性质']],'a polysyllabic word 是多音节词。许多词典在这里特别想到三音节以上的较长词；写作批评里也可能用来暗指用词太长、太装腔。','polysyllabic words；polysyllabic vocabulary；a polysyllabic expression。','monosyllabic 是一个音节；polysyllabic 是多个音节。词长不自动等于意思深奥。',('The editor replaced several polysyllabic words with simpler alternatives.','编辑把几个多音节长词换成了更简单的表达。'),('“Communication” is a polysyllabic word.','communication 是一个多音节词。'),sources=['https://www.etymonline.com/word/polysyllabic','https://www.oxfordlearnersdictionaries.com/definition/english/polysyllabic']),
E('epilepsy','/ˈepɪlepsi/','癫痫','一种与脑部活动有关、会导致反复发作倾向的疾病；发作的样子并不都一样。','希腊 epilēpsia 接 epilambanein 抓住、侵袭，经晚期拉丁 epilepsia、法语 épilepsie 等路线传入英语。',EPILEP+[['晚期拉丁 epilepsia → 法语 épilepsie / 英语 epilepsy','从古代侵袭、发作的名称发展为现代疾病名']],'have epilepsy 是患癫痫；live with epilepsy 是带着这种疾病生活。发作可能影响意识、感觉或动作，并不是每次都倒地抽搐；一次发作也不自动等于确诊癫痫。','have epilepsy；a diagnosis of epilepsy；people with epilepsy；epilepsy research。','seizure 是一次发作；epilepsy 是疾病名称。历史上的抓住是命名意象，不是疾病成因解释。',('The charity supports families affected by epilepsy.','这家慈善机构为受癫痫影响的家庭提供支持。'),('She spoke openly about living with epilepsy.','她坦诚地谈起了自己与癫痫共处的生活。'),sources=['https://www.etymonline.com/word/epilepsy','https://www.oxfordlearnersdictionaries.com/definition/english/epilepsy','https://www.nhs.uk/conditions/epilepsy/']),
E('epileptic','/ˌepɪˈleptɪk/','癫痫的；与癫痫发作有关的','把某种发作或相关表现限定到癫痫这一范围。','历史借入法语 épileptique，接晚期拉丁 epilepticus、希腊 epileptikos；与 epilepsy 同源，但不是把现代 -y 直接换成 -tic 就说明了真实借入过程。',LAB+[['希腊 epilambanein → epileptikos → 晚期拉丁 epilepticus','抓住、侵袭这一族形成的形容词'],['法语 épileptique → 英语 epileptic','与癫痫有关；后来也曾用作称人的名词']],'an epileptic seizure 是癫痫发作。旧文会用 an epileptic 称患者；叙述一个人时，a person with epilepsy 往往更合适。','an epileptic seizure；epileptic activity；types of epileptic seizure。','epilepsy 是病名；epileptic 是相关形容词。seizure 的原因不止一种，不要把所有发作都自动归为 epileptic。',('The leaflet describes several types of epileptic seizure.','这份资料介绍了几种癫痫发作类型。'),('The researchers compared recordings of epileptic activity.','研究人员比较了癫痫性活动的记录。'),sources=['https://www.etymonline.com/word/epileptic','https://www.oxfordlearnersdictionaries.com/definition/english/epileptic_1','https://www.nhs.uk/conditions/epilepsy/']),
E('narcolepsy','英 /ˈnɑːkəʊlepsi/；美 /ˈnɑːrkəˌlepsi/','发作性睡病','睡眠和清醒的调节出了问题，白天可能难以保持清醒，也可能突然入睡。','近代法语 narcolepsie 以希腊 narkē 麻木、昏沉和 -lepsie 发作构成，参照 épilepsie 的命名模式，再借入英语。',LAB+[['近代法语 narco- + -lepsie → narcolepsie → 英语 narcolepsy','把昏沉与发作的古典成分组合成睡眠疾病名称']],'have narcolepsy 是患发作性睡病。它不等于昨晚没睡好所以今天犯困；现代概念涉及睡眠与觉醒的调节，个人症状也有差别。','a diagnosis of narcolepsy；people with narcolepsy；narcolepsy research。','narcolepsy 与 epilepsy 共享发作这一构词成分，却是不同疾病。词尾相同不能据此当成一种病。',('The documentary explains how narcolepsy can affect working life.','这部纪录片解释了发作性睡病可能怎样影响工作生活。'),('He joined a support group for people with narcolepsy.','他加入了一个发作性睡病患者支持小组。'),sources=['https://www.etymonline.com/word/narcolepsy','https://www.oxfordlearnersdictionaries.com/definition/english/narcolepsy','https://www.nhs.uk/conditions/narcolepsy/','https://www.merriam-webster.com/dictionary/narcolepsy']),
E('moron','英 /ˈmɔːrɒn/；美 /ˈmɔːrɑːn/','蠢货〔侮辱性用语〕','说话人认为某人做了极蠢的事，用这个词把强烈的不满直接砸向对方。','近代取希腊 mōron，mōros 愚笨、迟钝的中性形式；最初进入旧医学分类，今天那种分类已过时，常见的是贬损骂人义。',MOR,'feel like a moron 可以是犯错后的自嘲；call someone a moron 则明显不客气。它不是中性地说一个人知识不足，也不是今天应当使用的医学诊断名。','feel like a moron；call someone a moron；a complete moron。','foolish 可以评价行为不明智；moron 是直接给人贴负面标签，语气更重。morose 阴郁来自另一条历史路线。',('I felt like a moron when I realized I had been pushing a door marked “Pull”.','发现自己一直在推一扇写着“拉”的门时，我觉得自己蠢透了。'),('She apologized for calling him a moron during the argument.','她为争吵时骂他蠢货而道歉。'),sources=['https://www.etymonline.com/word/moron','https://www.oxfordlearnersdictionaries.com/definition/english/moron']),
E('moronic','英 /məˈrɒnɪk/；美 /məˈrɑːnɪk/','愚蠢透顶的；蠢得离谱的','用很重的贬义评价一个主意、举动或作品，表示自己觉得它毫无脑子。','moron + -ic；加后缀后主重音后移，首音节也常弱化，不照 moron 的读法原样拼起来。',MOR+[['英语 moron + -ic → moronic','从贬损称人的名词形成形容词']],'a moronic idea 是蠢得离谱的主意；moronic behaviour 是极愚蠢的行为。它可以修饰事物，但语气仍然强烈，通常带说话人的恼火或轻蔑。','a moronic idea；moronic behaviour；a moronic comment。','unwise 比较克制地说不明智；moronic 带明显嘲讽和贬损，不是客观的难度或能力分级。',('He dismissed the proposal as a moronic idea.','他把这项提议斥为蠢得离谱的主意。'),('The reviewer called the dialogue moronic and repetitive.','评论者批评那些对白愚蠢又重复。'),sources=['https://www.etymonline.com/word/moronic','https://www.oxfordlearnersdictionaries.com/definition/english/moronic']),
]
